#include <iostream>
using namespace std;

#define AREA(w, h) ((w) * (h))

int main() {
    int a = 0;
    int b = 0;
    cin >> a;
    cin >> b;

    cout << "{word}：" << AREA(a + 1, b + 2) << endl;
    cout << AREA(a, b) << endl;
    return 0;
}
